// The expression language reference: one list drives the editor's autocomplete, the MCP guide resource and
// docs/expressions.md (generated by `expressionReferenceMarkdown`). Wording follows Adobe's public After Effects
// Expression Language Reference; differences of the Premiere-style object model are stated per entry.

export type RefScope = 'global' | 'comp' | 'layer' | 'property' | 'key' | 'marker' | 'selector';

export type RefEntry = {
	name: string;
	/** Insert text for autocomplete (`$` = cursor). */
	snippet?: string;
	signature: string;
	scope: RefScope;
	doc: string;
};

const g = (name: string, signature: string, doc: string, snippet?: string): RefEntry => ({
	name,
	signature,
	scope: 'global',
	doc,
	...(snippet ? { snippet } : {}),
});
const s =
	(scope: RefScope) =>
	(name: string, signature: string, doc: string, snippet?: string): RefEntry => ({
		name,
		signature,
		scope,
		doc,
		...(snippet ? { snippet } : {}),
	});
const L = s('layer');
const C = s('comp');
const P = s('property');
const K = s('key');
const M = s('marker');
const S = s('selector');

